SINA_SMART["parasito-aspergillosis"] = {"lecture":"parasito-aspergillosis","title":"Aspergillosis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-aspergillosis:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"parasito-aspergillosis:e0","text":"Aspergillus: ubiquitous mould, septate hyaline hyphae; A. fumigatus 90%.","topic":"The fungus","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e1","text":"Infection by inhaling conidia; construction works cause hospital outbreaks.","topic":"Epidemiology and risk factors","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e2","text":"Risk: neutropenia < 500 for > 10 days, corticosteroids, cavities (TB).","topic":"Epidemiology and risk factors","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e3","text":"Allergic forms: asthma (IgE), ABPA, extrinsic allergic alveolitis (precipitins).","topic":"Clinical forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e4","text":"ABPA: eosinophilia > 1000, high total IgE, mucous plugs.","topic":"Clinical forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e5","text":"Aspergilloma: fungus ball in a cavity; air-crescent sign; surgery.","topic":"Clinical forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e6","text":"IPA: fever resistant to antibiotics > 4 days in neutropenia; CT halo sign.","topic":"Clinical forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e7","text":"Galactomannan antigen: early marker; confirm on a 2nd sample; false positives with pip-tazo.","topic":"Diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e8","text":"IA classified as proven, probable or possible.","topic":"Diagnosis","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e10","text":"Prevention: sterile rooms, HEPA filters, posaconazole prophylaxis.","topic":"Treatment and prevention","sec":5,"importance":"core","highYield":"untested"},{"id":"parasito-aspergillosis:e9","text":"Voriconazole is the reference treatment of IPA; fluconazole inactive.","topic":"Treatment and prevention","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1469izu":"a","10xnze9":"a","1eftt4f":"a","1v375in":"a","1uflt2r":"a","odqr53":"a","1iqtbrw":"a","1gfhv3j":"a","fxoihd":"a","jdmdgv":"a","jqu2jx":"a","1dfklvd":"a","b76bjc":"a","mq6eae":"a","1rto17e":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-aspergillosis:s0":{"s":0,"u":["Aspergilloses are diseases due to cosmopolitan, opportunistic filamentous fungi of the genus Aspergillus , whose conidia we inhale constantly.","The spectrum goes from immunoallergic manifestations and localised colonisation (aspergilloma) to severe invasive multi-organ disease."],"dp":[]},"parasito-aspergillosis:e0":{"s":1,"u":["Aspergillus: ubiquitous mould, septate hyaline hyphae; A. fumigatus 90%.","Moulds with hyaline septate hyphae (hyalohyphomycetes); about 300 species: A. fumigatus (90%) , A. flavus , A. nidulans , A. niger , emerging A. terreus ."],"dp":[]},"parasito-aspergillosis:e1":{"s":2,"u":["Infection by inhaling conidia; construction works cause hospital outbreaks.","Risk factors: construction works (outbreaks in haematology; protect with laminar flow and HEPA filters); local (damaged epithelium, pre-formed cavities such as tuberculosis , smoking, cystic fibrosis, radiotherapy); general: profound prolonged neutropenia ( , corticosteroids , hereditary NADPH-oxidase deficiency (chronic granulomatous disease)."],"dp":[]},"parasito-aspergillosis:e2":{"s":2,"u":["Risk: neutropenia < 500 for > 10 days, corticosteroids, cavities (TB).","Risk factors: construction works (outbreaks in haematology; protect with laminar flow and HEPA filters); local (damaged epithelium, pre-formed cavities such as tuberculosis , smoking, cystic fibrosis, radiotherapy); general: profound prolonged neutropenia ( , corticosteroids , hereditary NADPH-oxidase deficiency (chronic granulomatous disease)."],"dp":[]},"parasito-aspergillosis:e3":{"s":3,"u":["Allergic forms: asthma (IgE), ABPA, extrinsic allergic alveolitis (precipitins).","Hypersensitivity : extrinsic allergic alveolitis (farmer's lung, mouldy hay or grain, pigeon feeding; type III/IV; cough, fever, dyspnoea 6-8 h after exposure, lasting 24-48 h; repeated attacks → interstitial fibrosis; anti-Aspergillus precipitins in non-atopic subjects); aspergillary asthma (type I; eosinophilia, specific IgE, positive skin tests); ABPA in asthma or cystic fibrosis (bronchial obstruction, productive cough, mucous plugs with Aspergillus, positive skin tests and precipitins, eosinophilia > 1000/mm³, raised total IgE)."],"dp":[]},"parasito-aspergillosis:e4":{"s":3,"u":["ABPA: eosinophilia > 1000, high total IgE, mucous plugs.","Hypersensitivity : extrinsic allergic alveolitis (farmer's lung, mouldy hay or grain, pigeon feeding; type III/IV; cough, fever, dyspnoea 6-8 h after exposure, lasting 24-48 h; repeated attacks → interstitial fibrosis; anti-Aspergillus precipitins in non-atopic subjects); aspergillary asthma (type I; eosinophilia, specific IgE, positive skin tests); ABPA in asthma or cystic fibrosis (bronchial obstruction, productive cough, mucous plugs with Aspergillus, positive skin tests and precipitins, eosinophilia > 1000/mm³, raised total IgE)."],"dp":[]},"parasito-aspergillosis:e5":{"s":3,"u":["Aspergilloma: fungus ball in a cavity; air-crescent sign; surgery.","Aspergilloma : fungus ball in a pre-existing cavity communicating with a bronchus; imaging shows the air crescent ('bell') sign ; haemoptysis.","Suspect it with fever resistant to broad-spectrum antibiotics for over 4 days in an immunocompromised patient; often pleuritic pain; CT: halo sign (perinodular haemorrhage), later air crescent."],"dp":[]},"parasito-aspergillosis:e6":{"s":3,"u":["IPA: fever resistant to antibiotics > 4 days in neutropenia; CT halo sign.","Suspect it with fever resistant to broad-spectrum antibiotics for over 4 days in an immunocompromised patient; often pleuritic pain; CT: halo sign (perinodular haemorrhage), later air crescent."],"dp":[{"h":"Why neutropenia is the key risk for invasive aspergillosis","t":"Macrophages kill inhaled conidia, but once conidia germinate into hyphae, neutrophils are the cells that destroy them. With fewer than 500 neutrophils for more than about ten days, hyphae grow unopposed into lung tissue and blood vessels, causing infarcts and haemorrhage, which is what the CT halo sign shows. Source: the lecture's defences and IPA slides."}]},"parasito-aspergillosis:e7":{"s":4,"u":["Galactomannan antigen: early marker; confirm on a 2nd sample; false positives with pip-tazo.","Serum galactomannan : twice-weekly screening during neutropenia; positive before cultures, imaging and symptoms; confirm on a second sample; false positives with piperacillin-tazobactam, amoxicillin-clavulanate and some foods. β-1,3-D-glucan : pan-fungal marker."],"dp":[{"h":"Why galactomannan changed the diagnosis","t":"Cultures and biopsies are slow or too risky in thrombocytopenic patients. Galactomannan is shed by growing Aspergillus into the blood, so twice-weekly screening can flag invasive infection days before symptoms or CT changes. Starting treatment earlier directly improves survival, as the lecture stresses: early diagnosis, better prognosis. Source: the lecture's galactomannan slides."}]},"parasito-aspergillosis:e8":{"s":4,"u":["IA classified as proven, probable or possible.","International criteria classify IA as proven (tissue hyphae with damage, or culture from a sterile site), probable or possible , combining host, clinical and mycological criteria."],"dp":[]},"parasito-aspergillosis:e10":{"s":5,"u":["Prevention: sterile rooms, HEPA filters, posaconazole prophylaxis.","Prevention : protective isolation in sterile rooms , HEPA filtration, strict hygiene during works; antifungal prophylaxis (posaconazole) in high-risk patients."],"dp":[]},"parasito-aspergillosis:e9":{"s":5,"u":["Voriconazole is the reference treatment of IPA; fluconazole inactive.","Antifungals : voriconazole (reference for IPA), other azoles (itraconazole, posaconazole, isavuconazole), amphotericin B (liposomal), echinocandins (caspofungin, micafungin); fluconazole and 5-FC are inactive; A. terreus resists amphotericin."],"dp":[]}},"meta":{"1469izu":{"a":"recall","vg":"parasito-aspergillosis:e0/recall/1"},"10xnze9":{"a":"recall","vg":"parasito-aspergillosis:e0/recall/2"},"1eftt4f":{"a":"recall","vg":"parasito-aspergillosis:s0/recall/1"},"1v375in":{"a":"relationship","vg":"parasito-aspergillosis:e1/relationship/1"},"1uflt2r":{"a":"recall","vg":"parasito-aspergillosis:e2/recall/1"},"odqr53":{"a":"recall","vg":"parasito-aspergillosis:e5/recall/1"},"1iqtbrw":{"a":"recall","vg":"parasito-aspergillosis:e5/recall/2"},"1gfhv3j":{"a":"recall","vg":"parasito-aspergillosis:e3/recall/1"},"fxoihd":{"a":"recall","vg":"parasito-aspergillosis:e4/recall/1"},"jdmdgv":{"a":"application","vg":"parasito-aspergillosis:e6/application/1"},"jqu2jx":{"a":"recall","vg":"parasito-aspergillosis:e6/recall/1"},"1dfklvd":{"a":"recall","vg":"parasito-aspergillosis:e7/recall/1"},"b76bjc":{"a":"relationship","vg":"parasito-aspergillosis:e7/relationship/1"},"mq6eae":{"a":"recall","vg":"parasito-aspergillosis:e9/recall/1"},"1rto17e":{"a":"recall","vg":"parasito-aspergillosis:e9/recall/2"}},"explRev":"4df58e0e8e50"};
